document.querySelector('.mobile-toggle').addEventListener('click',function(){const n=document.querySelector('.nav');const open=n.classList.toggle('open');this.setAttribute('aria-expanded',String(open));});document.querySelectorAll('.nav>details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.nav>details').forEach(o=>{if(o!==d)o.open=false;});}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.nav details').forEach(d=>d.open=false);document.querySelector('.nav').classList.remove('open');document.querySelector('.mobile-toggle').setAttribute('aria-expanded','false');}});document.addEventListener('click',e=>{if(!e.target.closest('.nav'))document.querySelectorAll('.nav>details').forEach(d=>d.open=false);});
const params=new URLSearchParams(location.search);const interest=document.querySelector('select[name="interest"]');if(interest&&params.has('plan')){const match=[...interest.options].find(o=>o.value.toLowerCase()===params.get('plan').toLowerCase());if(match)interest.value=match.value;}
document.querySelectorAll('.contact-form').forEach(form=>{let prepared='';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const subject=form.dataset.subject||('Rankin inquiry: '+(data.get('interest')||'Property management'));prepared=[['Name',data.get('name')],['Email',data.get('email')],['Phone',data.get('phone')],['Interest',data.get('interest')],['Property location',data.get('location')],['Message',data.get('message')]].filter(x=>x[1]).map(x=>x[0]+': '+x[1]).join('\n\n');location.href='mailto:support@rankinpropertymanagement.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(prepared);form.querySelector('.form-status').textContent='Your email draft is ready. Review and send it in your email app. Nothing has been submitted here.';form.querySelector('.copy-email').classList.remove('hidden');});form.querySelector('.copy-email').addEventListener('click',async e=>{e.preventDefault();try{await navigator.clipboard.writeText(prepared);form.querySelector('.form-status').textContent='Email text copied. Paste it into an email to support@rankinpropertymanagement.com.';}catch{let box=form.querySelector('.prepared-copy');if(!box){box=document.createElement('textarea');box.className='prepared-copy';box.setAttribute('aria-label','Prepared email text to copy');form.append(box);}box.value=prepared;box.focus();box.select();form.querySelector('.form-status').textContent='Copy the selected text and email it to support@rankinpropertymanagement.com.';}});});
document.querySelectorAll('.print-page').forEach(b=>b.addEventListener('click',()=>window.print()));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.resource-card').forEach(c=>c.hidden=b.dataset.filter!=='All'&&c.dataset.category!==b.dataset.filter);}));const search=document.getElementById('faq-search');if(search)search.addEventListener('input',()=>{let found=0;document.querySelectorAll('.faq-list .faq').forEach(f=>{f.hidden=!f.textContent.toLowerCase().includes(search.value.toLowerCase());if(!f.hidden)found++;});document.getElementById('faq-empty').hidden=found!==0;});
function calculate(kind,v){if(kind==='roi-calculator'){let collected=v.rent*12*(1-v.vacancy/100);let noi=collected*(1-v.fee/100)-v.tax-v.insurance-v.maintenance-v.other;let cf=noi-v.debt*12;return {main:cf/12,noi,cap:v.price?noi/v.price*100:null,coc:v.cash?cf/v.cash*100:null,collected};}if(kind==='vacancy-loss-calculator'){let daily=v.rent*12/365, carrying=v.carrying*12/365*v.days;return {main:daily*v.days,daily,carrying,combined:daily*v.days+carrying};}if(kind==='affordability-calculator'){let rent=v.income*v.percent/100;return {main:rent,housing:rent+v.utilities,remaining:v.income-rent-v.utilities};}if(kind==='rent-vs-sell-calculator'){let years=v.years;let cashflow=v.rent*12*(1-v.vacancy/100)*(1-v.fee/100)-v.operating-v.debt*12;let future=v.value*Math.pow(1+v.growth/100,years);let hold=future*(1-v.sale/100)-Math.max(0,v.balance-v.principal*years)+cashflow*years-v.ready;let sell=(v.value*(1-v.sale/100)-v.balance)*Math.pow(1+v.reinvest/100,years);return {main:hold-sell,hold,sell,cashflow,future};}}
window.rankinCalculate=calculate;const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});document.querySelectorAll('.calc-form').forEach(form=>{const result=form.nextElementSibling;const update=()=>{let valid=form.checkValidity();const v=Object.fromEntries([...new FormData(form)].map(([k,x])=>[k,Number(x)]));if(Object.values(v).some(x=>!Number.isFinite(x)))valid=false;let msg='';if(form.dataset.calc==='rent-vs-sell-calculator'&&(v.years<1||!Number.isInteger(v.years))){valid=false;msg='Use a whole number of years from 1 to 50.';}if(form.dataset.calc==='rent-vs-sell-calculator'&&v.principal>v.debt*12){valid=false;msg='Annual principal reduction cannot exceed annual debt payments.';}if(!valid){result.querySelector('.error').textContent=msg||'Enter valid non-negative amounts and percentages from 0 to 100.';result.querySelector('[data-main]').textContent='—';result.querySelectorAll('[data-result]').forEach(el=>el.textContent='—');return;}const r=calculate(form.dataset.calc,v);result.querySelector('.error').textContent='';result.querySelector('[data-main]').textContent=money.format(r.main);result.querySelectorAll('[data-result]').forEach(el=>{const x=r[el.dataset.result];el.textContent=x===null?'Not defined':(['cap','coc'].includes(el.dataset.result)?x.toFixed(1)+'%':money.format(x));});};form.addEventListener('input',update);update();});
const calcForm=document.querySelector('.calc-form');
if(calcForm && document.modelContext?.registerTool){
 const fields=[...calcForm.querySelectorAll('input[name]')];const lifecycle=new AbortController();
 const properties=Object.fromEntries(fields.map(f=>[f.name,{type:'number',minimum:Number(f.min||0),...(f.max?{maximum:Number(f.max)}:{}),description:f.parentElement.firstChild.textContent.trim()}]));
 const tool={name:'configure_rental_calculator',title:'Configure rental calculator',description:'Set inputs in the current rental planning calculator, update its visible results, and return the estimate. This does not save or submit information.',inputSchema:{type:'object',properties,additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){
  if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Expected an object of calculator inputs.');
  const v=Object.fromEntries([...new FormData(calcForm)].map(([k,x])=>[k,Number(x)]));
  for(const [k,x]of Object.entries(input)){const f=fields.find(f=>f.name===k);if(!f||typeof x!=='number'||!Number.isFinite(x)||x<Number(f.min||0)||(f.max&&x>Number(f.max)))throw new Error('Invalid calculator input: '+k);v[k]=x;}
  if(calcForm.dataset.calc==='rent-vs-sell-calculator'&&(!Number.isInteger(v.years)||v.years<1||v.principal>v.debt*12))throw new Error('Invalid years or principal reduction.');
  const stepBad=fields.some(f=>{const x=v[f.name],step=Number(f.step||1);return Math.abs((x-Number(f.min||0))/step-Math.round((x-Number(f.min||0))/step))>1e-7;});if(stepBad)throw new Error('Input precision does not match calculator fields.');
  const output=calculate(calcForm.dataset.calc,v);for(const f of fields)f.value=String(v[f.name]);calcForm.dispatchEvent(new Event('input',{bubbles:true}));return {calculator:calcForm.dataset.calc,inputs:v,results:output};
 }};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
